import { Button } from 'react-bootstrap'
import PracticeSessionConfigModal from './PracticeSessionConfigModal'
import PracticeSessionModal from './PracticeSessionModal'

export default function PracticeSessionButton(props) {
  const practice = props.practiceSession

  function handleStart(config) {
    if (!practice || !practice.startSession) return
    practice.startSession(config)
  }

  return (
    <>
      <Button
        variant="primary"
        size={props.buttonSize}
        className={props.buttonClassName || 'header-dropdown-btn'}
        title="Practice session"
        onClick={function() { if (practice && practice.openConfig) practice.openConfig() }}
      >
        {props.tunebook.icons.reviewsmall} Practice
      </Button>

      <PracticeSessionConfigModal
        show={practice && practice.configOpen}
        onHide={practice && practice.closeConfig}
        onStart={handleStart}
        error={practice && practice.planError}
        tunebook={props.tunebook}
        forceRefresh={props.forceRefresh}
        setBlockKeyboardShortcuts={props.setBlockKeyboardShortcuts}
      />

      <PracticeSessionModal
        show={practice && practice.sessionOpen}
        onStop={practice && practice.stopSession}
        onClose={practice && practice.stopSession}
        onNewSession={practice && practice.startNewSession}
        tunebook={props.tunebook}
        tunes={props.tunes}
        plan={practice && practice.plan}
        phase={practice && practice.phase}
        currentStep={practice && practice.currentStep}
        stepIndex={practice && practice.stepIndex}
        practiceViewMode={practice && practice.practiceViewMode}
        currentTempo={practice && practice.currentTempo}
        secondsRemaining={practice && practice.secondsRemaining}
        onWarmupEnded={practice && practice.advanceStep}
      />
    </>
  )
}
